import pandas as pd

tables = pd.read_html('data/docs/Ppcg23.html')

# Find TELEC header table - look for tables where first row, first col contains 'Variable:'
for i, t in enumerate(tables):
    if t.shape[0] >= 4 and t.shape[1] >= 2:
        s = str(t.iloc[0,0])
        if s.startswith('Variable:'):
            # Get the variable name from row 0, col 1
            var_name = str(t.iloc[0,1]).strip()
            if var_name == 'TELEC':
                print(f'=== Table {i} (TELEC header) ===')
                print(t.to_string())
                print()
                if i+1 < len(tables):
                    print(f'=== Table {i+1} (TELEC values) ===')
                    print(tables[i+1].to_string())
                break
